-- Generated by drizzle-kit for note / rating / photo.thumb_path; the FTS5 table and triggers at the
-- end are hand-written (drizzle-kit cannot model them), as in 0005. No change to recipe_fts or
-- to any recipe trigger. Owner decision Q2: private note text lives in this shared index and is
-- only ever returned through a query-time visibility join (note.shared = 1 OR note.user_id = me).
CREATE TABLE `note` (
	`id` text PRIMARY KEY NOT NULL,
	`recipe_id` text NOT NULL,
	`user_id` text NOT NULL,
	`body` text NOT NULL,
	`shared` integer DEFAULT false NOT NULL,
	`created_at` text NOT NULL,
	`updated_at` text NOT NULL,
	FOREIGN KEY (`recipe_id`) REFERENCES `recipe`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`user_id`) REFERENCES `user`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "note_body_len_chk" CHECK(length("note"."body") BETWEEN 1 AND 4000),
	CONSTRAINT "note_shared_chk" CHECK("note"."shared" IN (0, 1))
);
--> statement-breakpoint
CREATE INDEX `note_recipe_id_idx` ON `note` (`recipe_id`);--> statement-breakpoint
CREATE INDEX `note_user_id_idx` ON `note` (`user_id`);--> statement-breakpoint
CREATE TABLE `rating` (
	`recipe_id` text NOT NULL,
	`user_id` text NOT NULL,
	`stars` integer NOT NULL,
	`created_at` text NOT NULL,
	`updated_at` text NOT NULL,
	PRIMARY KEY(`recipe_id`, `user_id`),
	FOREIGN KEY (`recipe_id`) REFERENCES `recipe`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`user_id`) REFERENCES `user`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "rating_stars_chk" CHECK("rating"."stars" BETWEEN 1 AND 5)
);
