CREATE VIRTUAL TABLE IF NOT EXISTS `note_fts` USING fts5(
  note_id UNINDEXED,
  recipe_id UNINDEXED,
  body,
  tokenize = 'unicode61 remove_diacritics 2',
  prefix = '2 3'
);
