-- Backfill is a no-op on a 0006 database (no notes yet); kept so a re-run stays consistent.
INSERT INTO note_fts (note_id, recipe_id, body)
SELECT n.id, n.recipe_id, n.body FROM note n WHERE n.id NOT IN (SELECT note_id FROM note_fts);
