CREATE TRIGGER IF NOT EXISTS `note_fts_note_ai` AFTER INSERT ON `note`
BEGIN
  DELETE FROM note_fts WHERE note_id = new.id;
  INSERT INTO note_fts (note_id, recipe_id, body) VALUES (new.id, new.recipe_id, new.body);
END;
