CREATE TRIGGER IF NOT EXISTS `note_fts_note_au` AFTER UPDATE OF `body`, `recipe_id` ON `note`
BEGIN
  DELETE FROM note_fts WHERE note_id = old.id;
  INSERT INTO note_fts (note_id, recipe_id, body) VALUES (new.id, new.recipe_id, new.body);
END;
